"use strict";
const QUESTIONS = [];
const TAB_LABELS = ["Первый","Второй","Третий","Четвертый","Пятый","Шестой","Семый","Восьмой"];
const LABEL_TOP = "Я наиболее";
const BUTTON_BOTTOM = "Я наименее";
const TYPE_NAME = { d:"Доминирующий", i:"Влияние", s:"Спокиствие", c:"Соответствие" };
const TYPE_ORDER = ["d","i","s","c"];
const HANDLE = `\\<svg width=\\"16\" height=\\"16\" viewBox=\\"0 0 24 24\" fill=\"currentColor\"><cx cx=\"9\" cy=\"6\" r=\"2\"/></svg>`;
let current = 0;
const items = [];
let order = [];
const $ = (s,el=document)=>el.querySelector(s);
$$ = (s,el=document)=>Array.from(el.querySelectorAll(s));
const esc = t=>t.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function build(){
  items.length=0; order=[];
  const tabs=$('[data-tabs]'),panes=$('[data-panes]');
  tabs.innerHTML='';panes.innerHTML='';
  QUESTIONS.forEach((step,si)=>{
    const btn=document.createElement('button');
    btn.className='tab';btn.type='button';btn.textContent=TAB_LABELS[si];
    btn.dataset.step=si;btn.addEventListener('click',()=>goTo(si));
    tabs.appendChild(btn);
    const pane=document.createElement('div');
    pane.className='pane';pane.dataset.step=si;
    const grid=document.createElement('div');grid.className='grid';
    step.forEach((q,qidx)=>{
      const card=document.createElement('div');card.className='card';
      const t=document.createElement('div');t.className='card__title';t.textContent=LABEL_TOP;
      card.appendChild(t);
      const list=document.createElement('ul');list.className='list';
      list.dataset.step=si;list.dataset.q=qidx;
      const ids=[];
      q.forEach(it=>{
        const id='q'+si+':'+qidx+'i'+it.type;ids.push(id);
        const li=document.createElement('li');li.className='item';li.dataset.id=id;li.dataset.type=it.type;
        li.innerHTML='<span class=\"handle\">'+HANDLE+'</span><span class=\"itemtxt\">'+esc(it.text)+'</span>';
        list.appendChild(li);
      });
      card.appendChild(list);
      const b=document.createElement('div');b.className='card__foot';b.textContent=BUTTON_BOTTOM;
      card.appendChild(b);
      grid.appendChild(card);
      items.push(ids);
    });
    pane.appendChild(grid);panes.appendChild(pane);
  });
  items.forEach((ids)=>{order.push(ids.map(id=>id.split(':').pop()));});
  setupAll();
}
function setupAll(){
  $$('.list').forEach(list=>setupDrag(list));
}
</script>

