# -*- coding: utf-8 -*-
"""Build the final index.html inline (no external requests).
Data comes from /tmp/quest_final.json (verified 96/96 against source)."""
import json

QUESTIONS = json.load(open('/tmp/quest_final.json', encoding='utf-8'))

JQ = json.dumps(QUESTIONS, ensure_ascii=False)

CSS = r"""
:root{
  --bg:#0f1626;--bg2:#131d33;--card:#182338;--card2:#1f2c45;--line:#2c3b57;
  --txt:#eef2fb;--muted:#a3b3d0;--accent:#5b8cff;--accent2:#7a5bff;--ok:#4cd9a0;
  --d:#ff6b6b;--i:#ffd166;--s:#4cd9a0;--c:#6fc5ff;--r:16px;--shadow:0 24px 70px rgba(0,0,0,.5);
  --font:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  font-family:var(--font);color:var(--txt);
  background:radial-gradient(1200px 900px at 78% -12%,#1c2942 0%,rgba(28,41,66,0) 55%),var(--bg);
  min-height:100vh;line-height:1.5;-webkit-font-smoothing:antialiased
}
a{color:var(--accent)}
button{font-family:inherit}
.wrap{max-width:1080px;margin:0 auto;padding:40px 20px 84px}
.hero{text-align:center;padding:48px 20px 20px}
.badge{
  display:inline-block;letter-spacing:.12em;text-transform:uppercase;
  font-size:12px;color:var(--muted);border:1px solid var(--line);
  padding:6px 14px;border-radius:999px;margin-bottom:26px
}
h1{font-size:clamp(30px,5.2vw,54px);line-height:1.08;margin:0 0 18px;font-weight:800;letter-spacing:-.02em}
.h1-glow{
  background:linear-gradient(135deg,#bcd0ff,#a59bff);
  -webkit-background-clip:text;background-clip:text;color:transparent
}
.lead{font-size:clamp(16px,2.1vw,20px);color:var(--muted);max-width:620px;margin:0 auto 36px}
.btn-lg{
  appearance:none;border:0;cursor:pointer;display:inline-flex;align-items:center;gap:10px;
  font-size:18px;font-weight:700;padding:17px 40px;border-radius:13px;
  background:linear-gradient(135deg,var(--accent) 0%,var(--accent2) 100%);
  color:#fff;box-shadow:0 14px 36px rgba(91,140,255,.42);
  transition:transform .14s ease,box-shadow .2s ease
}
.btn-lg:hover{transform:translateY(-2px);box-shadow:0 18px 44px rgba(91,140,255,.5)}
.btn-lg:active{transform:translateY(0)}
.btn-lg:disabled{opacity:.45;cursor:default;transform:none;box-shadow:0 10px 26px rgba(91,140,255,.25)}
.hero-note{margin-top:16px;color:var(--muted);font-size:13.5px}
.features{
  display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));
  gap:16px;margin-top:64px
}
.feature{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:22px}
.feature .ic{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;margin-bottom:14px}
.feature h3{margin:0 0 6px;font-size:16px;font-weight:700}
.feature p{margin:0;color:var(--muted);font-size:14px}
.overlay{
  position:fixed;inset:0;background:rgba(6,10,20,.74);
  backdrop-filter:blur(4px);display:none;align-items:flex-start;
  justify-content:center;padding:40px 16px;z-index:100;overflow-y:auto
}
.overlay.open{display:flex}
.dialog{
  background:var(--bg2);border:1px solid var(--line);
  border-radius:var(--r);box-shadow:var(--shadow);width:100%;max-width:960px;
  position:relative;margin:0
}
.dialog__close{
  position:absolute;top:10px;right:10px;border:0;background:transparent;
  color:var(--muted);font-size:30px;line-height:1;cursor:pointer;width:40px;height:40px;
  border-radius:9px;transition:background .15s ease
}
.dialog__close:hover{background:var(--card2);color:var(--txt)}
.dialog__head{padding:28px 32px 22px}
.dialog__title{font-size:25px;margin:0 0 9px;font-weight:800;letter-spacing:-.01em}
.dialog__sub{color:var(--ok);font-weight:600;font-size:14px;margin:0 0 7px}
.dialog__lead{color:var(--muted);font-size:15px;margin:0}
.tabs{
  display:flex;flex-wrap:nowrap;gap:8px;padding:0 32px 10px;
  overflow-x:auto;scrollbar-width:thin
}
.tab{
  flex:1 0 auto;text-align:center;border:1px solid var(--line);
  background:var(--card);color:var(--muted);border-radius:10px;
  padding:11px 14px;cursor:pointer;font-size:14px;font-weight:600;
  transition:all .16s ease;min-width:76px;white-space:nowrap
}
.tab:hover{border-color:var(--accent);color:var(--txt)}
.tab.is-active{
  background:linear-gradient(135deg,var(--accent),var(--accent2));
  color:#fff;border-color:transparent;box-shadow:0 6px 18px rgba(91,140,255,.35)
}
.tab:disabled{opacity:.35;cursor:default}
.progress{height:6px;background:var(--line);margin:4px 32px 0;border-radius:999px;overflow:hidden}
.progress__bar{
  height:100%;width:12.5%;
  background:linear-gradient(90deg,var(--accent),var(--accent2));transition:width .35s ease
}
.panes{padding:10px 32px 6px}
.pane{display:none}
.pane.is-active{display:block;animation:fade .32s ease}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
@media(max-width:820px){.grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:600px){.grid{grid-template-columns:1fr}}
.card{background:var(--bg);border:1px solid var(--line);border-radius:13px;padding:14px 12px 12px}
.card__title,.card__foot{
  font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);
  font-weight:700;text-align:center
}
.card__foot{margin-top:12px}
ul.list{list-style:none;margin:10px 0 4px;padding:0;display:flex;flex-direction:column;gap:6px;user-select:none}
.item{
  flex:0 0 100%;display:flex;align-items:center;gap:11px;
  background:var(--card2);border:1px solid var(--line);
  border-radius:10px;padding:11px 13px;font-weight:600;font-size:14px;
  cursor:grab;touch-action:none;
  transition:box-shadow .12s ease,opacity .12s ease
}
.item:active{cursor:grabbing}
.item.dragging{opacity:.35}
.item.over{box-shadow:0 0 0 2px var(--accent)}
.item.locked{cursor:default}
.handle{flex:0 0 auto;display:grid;place-items:center;color:#6f80a3}
.handle svg{display:block}
.itemtxt{flex:1 1 auto}
.dragshadow{
  position:fixed;pointer-events:none;z-index:9999;opacity:.96;
  box-shadow:0 18px 40px rgba(0,0,0,.5)
}
.nav{
  display:flex;align-items:center;justify-content:space-between;
  padding:18px 32px 26px;border-top:1px solid var(--line);gap:12px
}
.btn-ghost{
  border:1px solid var(--line);background:transparent;color:var(--wided);
