'use strict';

var QUESTIONS = [];

var TAB_LABELS = ['Первый', 'Второй', 'Третий', 'Четвертый', 'Пятый', 'Шестой', 'Седьмой', 'Восьмой'];
var LABEL_NAMES = ['Я наиболее', 'Я наименее'];

var TYPE_NAME = {
  d: 'Доминирующий',
  i: 'Влияющий',
  s: 'Спокойный',
  c: 'Соответственный'
};

var HANDLE_SVG =
  '<svg width="18" height="16" viewBox="0 0 18 16" fill="currentColor" style="display:block">' +
  '<circle cx="4" cy="3" r="1.6"/><circle cx="14" cy="3" r="1.6"/>' +
  '<circle cx="4" cy="8" r="1.6"/><circle cx="14" cy="8" r="1.6"/>' +
  '<circle cx="4" cy="13" r="1.6"/><circle cx="14" cy="13" r="1.6"/>' +
  '</svg>';

var current = 0;
var items = [];
var order = [];

var $ = function (s, el) { return (el || document).querySelector(s); };
var $$ = function (s, el) { return Array.prototype.slice.call((el || document).querySelectorAll(s)); };

var ui = {};
var listState = [];

var STORAGE_KEY = 'disc_result_v1';

function esc(s) {
  return ('' + s).replace(/[&<>"']/g, function (c) {
    return {
      '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[c];
  });
}

/*
 * Build DOM from QUESTIONS: 8 steps, 3 questions each, 4 items each.
 * QUESTIONS.shape = 8 x [3 x [4 x {text, type}]]
 */
function build() {
  items.length = 0;
  order = [];
  var tabs = $('#tabs');
  var paneWrap = $('#panes');
  tabs.innerHTML = '';
  paneWrap.innerHTML = '';

  for (var s = 0; s < 8; s++) {
    var tab = document.createElement('button');
    tab.className = 'tab';
    tab.type = 'button';
    tab.textContent = TAB_LABELS[s];
    tab.setAttribute('data-step', s);
    (function (step) {
      tab.addEventListener('click', function () { go(step); });
    })(s);
    tabs.appendChild(tab);

    var pane = document.createElement('div');
    pane.className = 'pane';
    pane.setAttribute('data-step-pane', s);
    pane.style.display = 'none';

    var grid = document.createElement('div');
    grid.className = 'grid';

    for (var q = 0; q < 3; q++) {
      var quest = QUESTIONS[s][q];
      var card = document.createElement('div');
      card.className = 'card';

      var topLabel = document.createElement('div');
      topLabel.className = 'card__title';
      topLabel.textContent = LABEL_NAMES[0];
      card.appendChild(topLabel);

      var list = document.createElement('ul');
      list.className = 'list';
      list.dataset.step = s;
      list.dataset.q = q;

      var ids = [];
      var types = [];
      var i0 = quest;
      for (var it = 0; it < i0.length; it++) {
        var obj = i0[it];
        var id = 'q' + s + 'i' + q + 't' + obj.type;
        ids.push(id);
        types.push(obj.type);
        var li = document.createElement('li');
        li.className = 'item';
        li.dataset.id = id;
        li.dataset.type = obj.type;
        li.innerHTML = '<span class="handle">' + HANDLE_SVG + '</span><span class="itemtxt">' + esc(obj.text) + '</span>';
        list.appendChild(li);
      }
      card.appendChild(list);

      var footLabel = document.createElement('div');
      footLabel.className = 'card__foot';
      footLabel.textContent = LABEL_NAMES[1];
      card.appendChild(footLabel);

      grid.appendChild(card);
      items.push(ids);
    }
    pane.appendChild(grid);
    paneWrap.appendChild(pane);
  }

  items.forEach(function (ids) {
    order.push(ids.map(function (id) { return id[id.length - 1]; }));
  });

  listState = items.map(function (ids) { return ids.map(function () { return 'off'; }); });

  wire();
  goTo(0);
}

function wire() {
  $('.btn-lg, #startBtn, #goBtn').forEach(function (b) { b.addEventListener('click', openWizard); });
  $('#openBtn').addEventListener('click', openWizard);
  $$('[data-close]').forEach(function (b) { b.addEventListener('click', closeWizard); });
  $('#navPrevBtn').addEventListener('click', prevStep);
  $('#navNextBtn').addEventListener('click', nextStep);
  $('#navFinishBtn').addEventListener('click', finish);
  $$('[data-step]').sort(function (a, b) {
    return (+a.getAttribute('data-step')) - (+b.getAttribute('data-step'));
  }).forEach(function (tab) { tab.addEventListener('click', (function (t) { return function () { go(+t.getAttribute('data-step')); }; })(tab)); });
  setAllListens();
}

function setAllListens() {
  listState = items.map(function (ids) {
    return ids.map(function () { return 'off'; });
  });
  $$('ul.list').summarizeSort();
  $$('ul.list').forEach(function (ul) {
    drag(ul);
  });
}

function openWizard() {
  $('#overlay').classList.add('is-open');
  document.body.style.overflow = 'hidden';
}

function closeWizard() {
  $('#overlay').classList.remove('is-open');
  document.body.style.overflow = '';
}

function goTo(step) {
  current = step;
  var tabs = $$('[data-step]');
  tabs.forEach(function (t, idx) {
    t.classList.toggle('is-active', idx === step);
  });
  $$('[data-step-pane]').forEach(function (p) {
    var s = +p.getAttribute('data-step-pane');
    p.style.display = (s === step) ? 'block' : 'none';
  });
  prog.classList.toggle('hidden', false);
  prog.style.width = ((step + 1)) + '%';
  navPrev.classList.toggle('disabled', step === 0);
  if (step === 0) {
    navPrev.disabled = true;
  } else {
    navPrev.disabled = false;
  }
  if (step === 7) {
    navNext.hidden = true;
    navFinish.hidden = false;
  } else {
    navFinish.hidden = true;
    navNext.hidden = false;
  }
  navHint.textContent = 'Шаг ' + (step + 1) + ' из 8';
  refresh();
}

function refresh() {
  var allDone = listState.every(function (q) {
    return q.every(function (v) { return v !== 'off'; });
  });
  next.disabled = !allDone;
}

function nextStep() {
  if (current < 7) {
    goTo(current + 1);
  } else {
    finish();
  }
}

function prevStep() {
  if (current > 0) {
    goTo(current - 1);
  }
}

function finish() {
  // listState holds, for each step, each of 4 items' type in top-bottom order.
  var finalOrder = listState.map(function (q) {
    return q.slice().sort(function (a, b) { return a - b; });
  });
  var disc = calculateDisc(finalOrder);
  render(disc);
}

function render(disc) {
  var result = document.getElementById('result');
  result.className = 'result';
  result.style.display = 'block';

  var orderDesc = ['d', 'i', 's', 'c'].sort(function (a, b) {
    return disc[b] - disc[a];
  });
  var top = orderDesc[0];
  var topScore = disc[top];

  var parts = [];
  parts.push('<div class="disc__title">Ваш результат DISC</div>');
  parts.push('<div class="disc__scores">');
  ['d', 'i', 's', 'c'].forEach(function (k, idx) {
    var val = disc[k];
    parts.push('<div class="disc__col ' + k + '">' +
      '<div class="disc__letter">' + k.toUpperCase() + '</div>' +
      '<div class="disc__val">' + val + '</div>' +
      '</div>');
  });
  parts.push('</div>');
  parts.push('<div class="disc__order">Ранжирование: ' + orderDesc.map(function (k) { return k.toUpperCase(); }).join(' → ') + '</div>');
  parts.push('<div class="disc__bars">');
  ['d', 'i', 's', 'c'].forEach(function (k) {
    var v = disc[k];
    var fill = Math.min(100, Math.min(3, Math.max(1, Math.abs(v))) * (100 / 3) * 0.5);
    parts.push('<div class="disc__bar ' + k + '">' +
      '<div class="disc__bar__fill" style="width:' + fill + '%"></div>' +
      '<div class="disc__bar__label">' + k.toUpperCase() + ' ' + v + '</div>' +
      '</div>');
  });
  parts.push('<script>if(window.disc){window.disc.score=' + JSON.stringify(disc) + '}<\/script>');
  parts.push('</div>');

  result.innerHTML = parts.join('');
  navNext.hidden = true;
  navFinish.disabled = true;

  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify({ v: 1, ts: Date.now(), score: disc }));
  } catch (e) {}
}

function calculateDisc(order) {
  var disc = { d: 0, i: 0, s: 0, c: 0 };
  var perQ = order.length; // 8
  for (var s = 0; s < perQ; s++) {
    var qList = order[s]; // 4 types, major(minus) first ... minor(last)
    var topType = qList[0]; // "off" stays off
    if (topType !== 'off') { disc[topType]++; }
    var botType = qList[qList.length - 1];
    if (botType !== 'off') { disc[botType]--; }
  }
  return disc;
}

