.score.d .val { color: var(--d); }
.score.i .letter,
.score.i .val { color: var(--i); }
.score.s .letter,
.score.s .val { color: var(--s); }
.score.c .letter,
.score.c .val { color: var(--c); }

.bars {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 32px;
}

.barcell {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 15px;
}

.barcell .bt {
  font-size: 22px;
  font-weight: 800;
}

.barcell .bl {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--muted);
  margin: 0 0 10px;
}

.tracks {
  position: relative;
  background: var(--card2);
  border-radius: 999px;
  height: 10px;
  overflow: hidden;
}

.tracks::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--line);
}

.fill {
  position: absolute;
  top: 0;
  bottom: 0;
  border-radius: 999px;
  transition: width .5s ease;
}

.fill.pos {
  left: 50%;
}

.fill.neg {
  right: 50%;
}

.order {
  font-size: 15px;
  margin: 16px 0 0;
  color: var(--muted);
}

.order b {
  color: var(--txt);
  letter-spacing: .08em;
}

.disclaimer {
  background: var(--card1);
  border: 1px solid var(--line);
  border-left: 3px solid var(--accent);
  border-radius: 12px;
  padding: 18px 22px;
  color: var(--muted);
  font-size: 14px;
  margin: 40px 0 0;
}

.disclaimer b {
  color: var(--txt);
}

@media (max-width: 600px) {
  .dialog__head,
  .tabs,
  .panes,
  .nav { padding-left: 16px; padding-right: 16px; }
  .progress { margin: 4px 16px 0; }
  .nav__hint { display: none; }
  .bars { grid-template-columns: repeat(2, 1fr); }
  .result { padding: 26px 20px 32px; }
  .scores { gap: 22px; }
}

