'use strict';
window.DISCTest = (function () {
  'use strict';
  var QUESTIONS = /*@data_placeholder_QUESTIONS@*/ [];
  var WIZARD_TABS = /*@data_placeholder_TABS@*/ [];
  var LABEL_TOP = 'Я наиболее';
  var LABEL_BOT = 'Я наименее';
  var TYPE_NAMES = { d: 'Доминирующий', i: 'Влияющий', s: 'Спокойный', c: 'Соответственный' };
  var DISC_ORDER = ['d', 'i', 's', 'c'];
  var HANDLE_SVG = '<svg width="18" height="18" viewBox="0 0 24 24" style="display:block"></svg>';
  var STORAGE_KEY = 'disc_scores_v3';
  var STEP_N = 8;

  var current = 0;
  var dragMap = [];
  var dom = [];
  var dragMoving = null;

  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }

  function esc(value) {
    return String(value == null ? '' : value).replace(/[<>"']/g, function (ch) {
      return { '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
    });
  }

  /* ---- scoring ----
   * For each list, top item (index 0) => +1 to its type,
   * bottom item (index 3) => -1 to its type. Middle (1,2) ignored.
   * Sum across all 3 lists per step, across all 8 steps. */
  function calculateScores(order) {
    var scores = { d: 0, i: 0, s: 0, c: 0 };
    for (var s = 0; s < STEP_N; s++) {
      for (var q = 0; q < 3; q++) {
        var list = order[s][q];
        if (list.length < 2) continue;
        var top = list[0];
        var bot = list[list.length - 1];
        if (top && scores[top]) scores[top]++;
