  function openWizard() {
    if (overlay) overlay.style.display = 'block';
    if (home) home.style.display = 'none';
  }

  function closeWizard() {
    if (overlay) overlay.style.display = 'none';
    if (home) home.style.display = 'block';
  }

  function showCurrentPane() {
    var panes = $('#panes').querySelectorAll('.pane');
    panes.forEach(function (p) {
      var step = parseInt(p.getAttribute('data-step-pane'), 10);
      p.style.display = step === current ? 'block' : 'none';
    });
    var buttons = $('#tabs').querySelectorAll('.tab');
    buttons.forEach(function (b) {
      var step = parseInt(b.getAttribute('data-step'), 10);
      b.classList.toggle('is-active', step === current);
    });
    updateNavButtons();
  }

  function updateNavButtons() {
    if (prevBtn) {
      prevBtn.disabled = current === 0;
    }
    if (current >= STEP_N - 1) {
      if (nextBtn) nextBtn.style.display = 'none';
      if (finishBtn) finishBtn.style.display = 'inline-block';
    } else {
      if (nextBtn) nextBtn.style.display = 'inline-block';
      if (finishBtn) finishBtn.style.display = 'none';
    }
    var allComplete = isStepComplete(current);
    if (nextBtn) nextBtn.disabled = !allComplete;
  }

  function isStepComplete(step) {
    for (var q = 0; q < PER_Q; q++) {
      var list = $('ul[data-step="' + step + '"][data-q="' + q + '"]');
      if (!list || list.querySelectorAll('.item').length !== PER_ITEM) return false;
    }
    return true;
  }

  function goNext() {
    if (!isStepComplete(current)) return;
    current++;
    showCurrentPane();
  }

  function goBack() {
    if (current > 0) {
      current--;
      showCurrentPane();
    }
  }

  function showResults() {
    var scores = calculateScores();
    var total = 0;
    DISC_ORDER.forEach(function (t) { total += Math.abs(scores[t]); });
    var max = Math.max(Math.abs(scores.d), Math.abs(scores.i), Math.abs(scores.s), Math.abs(scores.c));

    if (resultScores) {
      resultScores.innerHTML = '';
      DISC_ORDER.forEach(function (t) {
        var cell = el('div', 'result-score');
        var letter = el('div', 'result-score-letter');
        letter.textContent = t.toUpperCase();
        cell.appendChild(letter);
        var val = el('div', 'result-score-val');
        val.textContent = scores[t] > 0 ? ('+' + scores[t]) : scores[t];
        cell.appendChild(val);
        resultScores.appendChild(cell);
      });
    }

    if (resultCard) {
      var top = DISC_ORDER.slice().sort(function (a, b) { return Math.abs(scores[b]) - Math.abs(scores[a]); })[0];
      var desc = el('div', 'result-top');
      desc.innerHTML = 'Ваш доминирующий тип: <b>' + top.toUpperCase() + '</b> &mdash; ' + TYPE_NAMES[top];
      resultCard.appendChild(desc);
    }

    if (overlay) overlay.style.display = 'none';
    if (home) home.style.display = 'none';
    if (resultsView) {
      resultsView.style.display = 'block';
      resultsView.scrollIntoView({ behavior: 'smooth' });
    }
    var data = { scores: scores, top: top, total: total, max: max };
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch (e) {}
  }

  function init() {
    buildTabs();
    buildPanes();
    initDom();
    showHome();
    showCurrentPane();

    if (nextBtn) nextBtn.addEventListener('click', goNext);
    if (finishBtn) finishBtn.addEventListener('click', showResults);
    if (prevBtn) prevBtn.addEventListener('click', goBack);

    // wire close on tab click? no; keep tabs as progress only
  }

  document.addEventListener('DOMContentLoaded', init);

  return {
    calculateScores: calculateScores,
    getScores: function () { return calculateScores(); }
  };
};
