'use strict';
window.DISCTest = function () {
  'use strict';
  var QUESTIONS = /*__QUESTIONS__*/ [];
  var WIZARD_TABS = /*__WIZARD_TABS__*/ [];
  var LABEL_TOP = 'Я наиболее';
  var LABEL_BOT = 'Я наименее';
  var TYPE_NAMES = { d: 'Доминирующий', i: 'Влияющий', s: 'Спокойный', c: 'Соответственный' };
  var HANDLE_SVG = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24"><circle cx="6" cy="6" r="1.5" fill="currentColor"/><circle cx="18" cy="6" r="1.5" fill="currentColor"/><circle cx="6" cy="12" r="1.5" fill="currentColor"/><circle cx="18" cy="12" r="1.5" fill="currentColor"/><circle cx="6" cy="18" r="1.5" fill="currentColor"/><circle cx="18" cy="18" r="1.5" fill="currentColor"/></svg>';
  var STORAGE_KEY = 'disc_scores_v3';
  var STEP_N = 8;
  var PER_Q = 3;
  var PER_ITEM = 4;

  var current = 0;
  var dragMap = [];
  var domItems = [];
  var dragState = null;

  var el = function (tag, cls) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    return node;
  };
  var $ = function (s, r) { return (r || document).querySelector(s); };

  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (ch) {
      switch (ch) {
        case '&': return '&amp;';
        case '<': return '&lt;';
        case '>': return '&gt;';
        case '"': return '&quot;';
        case "'": return '&#39;';
      }
    });
  }

  function calculateScores() {
    var scores = { d: 0, i: 0, s: 0, c: 0 };
    for (var s = 0; s < STEP_N; s++) {
      for (var q = 0; q < PER_Q; q++) {
        var list = dragMap[s][q];
        var top = list[0];
        var bot = list[list.length - 1];
        if (scores[top]) scores[top]++;
        if (scores[bot]) scores[bot]--;
      }
    }
    return scores;
  }

  function reorderList(step, q, fromPos, toPos) {
    var arr = dragMap[step][q];
    var moved = arr.splice(fromPos, 1)[0];
    var insert = toPos > fromPos ? toPos - 1 : toPos;
    if (insert < 0) insert = 0;
    if (insert > arr.length) insert = arr.length;
    arr.splice(insert, 0, moved);
    renderList(step, q);
  }

  function renderList(step, q) {
    var listEl = $('ul[data-step="' + step + '"][data-q="' + q + '"]');
    if (!listEl) return;
    listEl.innerHTML = '';
    dragMap[step][q].forEach(function (type, pos) {
      var li = el('li', 'item');
      li.setAttribute('data-type', type);
      li.setAttribute('data-pos', pos);
      var handle = el('span', 'handle');
      handle.innerHTML = HANDLE_SVG;
      li.appendChild(handle);
      var txt = el('span', 'itemtxt');
      txt.textContent = type;
      li.appendChild(txt);
      listEl.appendChild(li);
    });
    updateCardState(step, q);
  }

  function updateCardState(step, q) {
    var listEl = $('ul[data-step="' + step + '"][data-q="' + q + '"]');
    var btn = $('button[data-complete="' + step + '-' + q + '"]');
    if (!listEl) return;
    var items = listEl.querySelectorAll('.item');
    // find completion marker in DOM
    var mark = listEl.querySelector('.list-complete');
    if (items.length === PER_ITEM) {
      if (!mark) { mark = el('i', 'list-complete'); listEl.appendChild(mark); }

